            std::fprintf(stderr, "[ledgerfast] polygons %llu, skipped as covered %llu; vertices %llu, from the draw's cache %llu; band divisions saved %llu; verify: %llu draws checked, %llu differ\n", static_cast<unsigned long long>(g_ledFastPolys),
                         static_cast<unsigned long long>(g_ledFastSkipped), static_cast<unsigned long long>(g_ledFastVerts), static_cast<unsigned long long>(g_ledFastVertHits), static_cast<unsigned long long>(g_ledQuotReused),
                         static_cast<unsigned long long>(g_ledFastChecked), static_cast<unsigned long long>(g_ledFastBad));
        if (g_ledBandSkipped || g_ledBandRun)
            std::fprintf(stderr, "[ledgerband] MSC_VGX_LEDGERBAND=%d: bands walked %llu, left out as already holding the polygon %llu; edges culled before their divisions %llu; corner screen positions from the draw's cache %llu, made %llu\n", LedgerBandOn() ? 1 : 0, static_cast<unsigned long long>(g_ledBandRun), static_cast<unsigned long long>(g_ledBandSkipped), static_cast<unsigned long long>(g_ledEdgeCulled), static_cast<unsigned long long>(g_ledSpHits), static_cast<unsigned long long>(g_ledSpMade));
