        case CMD_COPY_TEX:
            if ((g_huntMask & hunt::COPIES) && !vgx::copyguard::At(buf, c.arg).fromPass && !vgx::copyguard::At(buf, c.arg).srcTex && !vgx::copyguard::At(buf, c.arg).depth && !vgx::copyguard::At(buf, c.arg).skip && g_memoSkipTo != static_cast<size_t>(g_rt.cmd)) { ++hunt::g_dropD[9]; break; }   // (MSC_VGX_HUNT copies: an EFB colour copy that is not made)
            if (g_memoSkipTo == static_cast<size_t>(g_rt.cmd)) { g_memoSkipTo = kNoCmd; MemoSkippedCopy(vgx::copyguard::At(buf, c.arg)); break; }
            CopyTex(vgx::copyguard::At(buf, c.arg));
            break;
        case CMD_COPY_DISP: CopyDisp(buf.copyDisp[c.arg]); break;
        case CMD_PRESENT:
            if (ShcOn() && !replay) ++g_shcCount[std::string("frames.") + ShcSceneName(buf.scene)];
            if (ShcOn()) ShcPresent(buf.frame);
            if (FgcOn() && !replay) FgcPresent(buf);
            if (g_tcMode > 0 && !replay) TcPicture();   // (wave 15 MSC_VGX_TEX_COMPRESS)
            if (FscEvery() > 0 && !replay) FscPresent(buf.frame);
            if (!replay && (gs20::PbOn() || gs20::TcOn())) { if (gs20::PbOn()) gs20::PbPresent(gs20::EnvNum("MSC_VITA_PB_MIB", 16)); if (gs20::TcOn()) gs20::TcPresent(buf.scene == 1); }   // (gpuscene20: MSC_VGX_PBEST, MSC_VGX_TEXCENSUS20; scene 1 = play)
            if ((FxStatOn() || ShcOn()) && !replay && buf.frame % 600 == 599) FxStatPrint(buf.frame);
            if (GenStatOn() && buf.frame % 600 == 0) GenStatPrint();
