extern "C" uint32_t VgxGpuSceneSkip(void) { return vgx::backend::g_sceneSkip.load(std::memory_order_relaxed); }   // nxr6a: timed frames of the old scene still in flight at the reset: the host drops them too
extern "C" int VgxGpuSampleIdle(void) { return vgx::backend::GpuIdleSkipOn() && vgx::backend::g_idlePic.Discard() ? 1 : 0; }   // nxr3a MSC_GPU_IDLE_SKIP: the newest GPU sample may be a picture that drew nothing (the host's queue judge skips it too)
