extern "C" int VgxDynResDescribe(char* out, int size) {   // 1.2: one line for the run header of the logs (np_vita_platform.cpp, the harness)
    const vgx::backend::DynRes& d = vgx::backend::g_dyn;
    if (!d.inited) return std::snprintf(out, static_cast<size_t>(size), "dynres=not started yet");
    if (!d.on) return std::snprintf(out, static_cast<size_t>(size), "dynres=off (the game's own size)");
    return std::snprintf(out, static_cast<size_t>(size),
                         "dynres=on rules %d, ordinary scenes %.2f..%.2f per side (60 fps floor %.2f, replay/celebration floor %.2f at 30), Mega Strikes %s, larger pictures: %.0f%% for %.1f s, back at %.0f%%, gap %d",
                         d.rules, vgx::backend::g_lv[d.floorLevel].s, vgx::backend::g_lv[d.minLevel].s, vgx::backend::g_lv[std::max(d.floorLevel, d.floor60)].s,
                         vgx::backend::g_lv[std::max(d.floorLevel, d.pacedFloor)].s, d.megaMode < 0 ? "as ordinary" : (d.megaMode == 1 ? "fixed" : (vgx::backend::g_smoothFloors || vgx::backend::g_qualityFloors ? "to the floor" : "down to 0.50")),
                         d.upAbove * 100.0f, d.upSecs, d.downAbove * 100.0f, d.gap);
}
// 1.2: the graphics settings the Settings screen controls, as the code in force reads them (the second line of the run header; tools/settings-audit checks it per choice).
extern "C" int VgxGfxDescribe(char* out, int size) {
    using namespace vgx::backend;
    char render[24] = "dynamic";
    if (g_fixedW) std::snprintf(render, sizeof render, "fixed %dx%d", g_fixedW, g_fixedH);
    static const char* const sceneName[4] = {"other", "play", "replay", "nis"};
    char scenes[40] = "";
    for (int i = 0; i < 4; ++i)
        if (FxSceneMask() & (1u << i)) std::snprintf(scenes + std::strlen(scenes), sizeof scenes - std::strlen(scenes), "%s%s", scenes[0] ? "+" : "", sceneName[i]);
    if (!scenes[0]) std::snprintf(scenes, sizeof scenes, "none");
    const int fxDiv = FxDiv();
    return std::snprintf(out, static_cast<size_t>(size), "gfx: render=%s msaa=%s larger-pictures=%s foreground-first=%s hdtex=%s effects-pass=%s extra-scenes=%s min-px=%d fx-max-lines=%d", render,
                         g_msaaTop >= 4 ? "4x+2x" : (g_msaaTop >= 2 ? "2x" : "off"),
                         !g_dyn.inited ? "?" : (!g_dyn.on ? "off (dynres off)" : (g_lv[g_dyn.minLevel].s > 1.001f ? "up to 1.2 per side" : (g_msaaTop >= 2 && g_dyn.minLevel < g_lvNative ? "multisampled only" : "none"))),
                         vgx::FgRequested() ? "on" : "off", vgx::hdtex::Requested() == 0 ? "off" : (vgx::hdtex::Requested() == 2 ? "dry run" : (vgx::hdtex::Mode() ? "on" : "on, no pack")),
                         fxDiv == 0 ? "off" : (g_fxAlways ? "always" : (fxDiv == 4 ? "sixteenth" : "quarter")), scenes, FxMinPx(), FxMaxH());
}
extern "C" void VgxHeavyStadium(int on) { vgx::backend::g_heavyStadium.store(on ? 1 : 0, std::memory_order_relaxed); }   // MSC_STADIUM_HEAVY (StadiumHeavy.cpp)
// on: bit 0 the cadence holds the scene at 30 with MSC_CADENCE_FULL on, bit 1 MSC_CADENCE_FULL is on, bit 2 the scene is held at 30 by any rule (np_fps.cpp)
extern "C" void VgxCadenceFull(int on) {
    if (on & 2) vgx::backend::g_cadFullSeen.store(1, std::memory_order_relaxed);
    vgx::backend::g_cadFull.store((on & 2) && (on & 1) ? 1 : 0, std::memory_order_relaxed);
    vgx::backend::g_held30.store((on & 5) ? 1 : 0, std::memory_order_relaxed);
}
extern "C" void VgxPacedSceneHint(int on) { vgx::backend::g_pacedScene.store(on, std::memory_order_relaxed); }
extern "C" int VgxFgCrowdThrottle(void) {   // W12 FG: how many times rarer the crowd impostors are refreshed (1: as the game does; 2: half as often)
    return ((vgx::backend::g_fgNow.load(std::memory_order_relaxed) & 2) || vgx::backend::g_l60Crowd.load(std::memory_order_relaxed) || vgx::backend::g_holdCrowd.load(std::memory_order_relaxed)) ? 2 : 1;
}
extern "C" int VgxLock60ShadowStep(void) { return vgx::backend::g_l60Shadow.load(std::memory_order_relaxed); }   // 1.3 MSC_LOCK60: frames added to a visible player's shadow interval (0..2)
extern "C" int VgxHoldShadowStepFor(int key) {   // 1.3 MSC_PICTURE_HOLD: key 0..7 of a player: the shadow step reaches player k (k * 24 ticks) after the change, so no two players change on one frame
    const uint32_t d = vgx::backend::g_holdTickNo.load(std::memory_order_relaxed) - vgx::backend::g_holdShadowAt.load(std::memory_order_relaxed);
    return d >= static_cast<uint32_t>((key & 7) * 24) ? vgx::backend::g_holdShadow.load(std::memory_order_relaxed) : vgx::backend::g_holdShadowOld.load(std::memory_order_relaxed);
}
extern "C" int VgxHoldShadowStep(void) { return vgx::backend::g_holdShadow.load(std::memory_order_relaxed); }   // 1.3 MSC_PICTURE_HOLD: 0 none, 1 far players' shadow pictures less often, 2 every player's
extern "C" void VgxStadiumIs(int stadium) { vgx::backend::g_holdStadium.store(stadium, std::memory_order_relaxed); }   // 1.3 MSC_PICTURE_HOLD: the stadium of the match (StadiumHeavy.cpp), -1 none
